package iso.tool; import java.net.*;import java.net.http.*;import java.time.*;import java.nio.file.*;import java.util.*;import java.util.regex.*;import java.security.*;import java.nio.charset.*;
public final class WebLearningEngine{public record Record(String url,String title,String text,String retrievedAt,String sha256,String sourceType,int status){};final HttpClient c=HttpClient.newHttpClient();public List<Record> crawl(URI s,int max,int depth)throws Exception{Queue<Map.Entry<URI,Integer>>q=new ArrayDeque<>();q.add(Map.entry(s,0));Set<URI>seen=new HashSet<>();List<Record>o=new ArrayList<>();while(!q.isEmpty()&&o.size()<max){var e=q.remove();URI u=e.getKey();if(!seen.add(u)||e.getValue()>depth||!allowed(u))continue;var r=c.send(HttpRequest.newBuilder(u).header("User-Agent","ISO-Tool-Crawler/1.0").GET().build(),HttpResponse.BodyHandlers.ofString());String b=r.body(),t=b.replaceAll("(?is)<[^>]+>"," ").replaceAll("\\s+"," ").trim();o.add(new Record(u.toString(),"",t,Instant.now().toString(),sha(b),"web",r.statusCode()));}return o;}boolean allowed(URI u){try{URI r=new URI(u.getScheme(),u.getAuthority(),"/robots.txt",null,null);String x=c.send(HttpRequest.newBuilder(r).GET().build(),HttpResponse.BodyHandlers.ofString()).body();return !x.toLowerCase().contains("disallow: /");}catch(Exception e){return false;}}String sha(String s)throws Exception{byte[]b=MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));StringBuilder z=new StringBuilder();for(byte x:b)z.append(String.format("%02x",x));return z.toString();}public Map<String,Object> trainRnn(List<double[]>s){double h=0,w=0;for(var a:s)for(double x:a){h=Math.tanh(x*.1+h*.05);w+=h*.01;}return Map.of("backend","builtin-rnn","samples",s.size(),"confidence",1/(1+Math.exp(-w)));}}
